using namespace Aevrynd;

namespace {
Mesh3D UvCard(){Mesh3D mesh;const auto normal=PackNormalSnorm8({0,0,-1});const auto white=PackColorRgba8({1,1,1,1});mesh.vertices={{-2,-1,0,normal,white,0,1},{-2,1,0,normal,white,0,0},{2,1,0,normal,white,1,0},{2,-1,0,normal,white,1,1}};mesh.indices={0,1,2,0,2,3};return mesh;}
float HalfToFloat(std::uint16_t value){const std::uint32_t sign=std::uint32_t(value&0x8000u)<<16,exponent=(value>>10)&31u,mantissa=value&1023u;std::uint32_t bits{};if(!exponent){if(!mantissa)bits=sign;else{std::uint32_t normalized=mantissa,shift{};while((normalized&0x400u)==0){normalized<<=1;++shift;}bits=sign|((127u-15u-shift)<<23)|((normalized&0x3ffu)<<13);}}else if(exponent==31u)bits=sign|0x7f800000u|(mantissa<<13);else bits=sign|((exponent+112u)<<23)|(mantissa<<13);return std::bit_cast<float>(bits);}
struct Capture{LinearHdrReadback3D hdr{};ObjectIdCapture3D oid{};std::vector<uint8_t> mask{};std::vector<std::array<float,3>> rgb{};float luma{};size_t pixels{};};
float Channel(const LinearHdrReadback3D& capture,size_t pixel,unsigned channel){const size_t offset=pixel*8+channel*2;std::uint16_t value{};std::memcpy(&value,capture.rawHalfBytes.data()+offset,2);return HalfToFloat(value);}
std::optional<Capture> CaptureCard(D3D12Renderer& renderer,const DrawList& draw,RenderObjectIdentity3D identity,uint64_t serial,const Capture* stableMask=nullptr){
 const ObjectIdCaptureRequestMetadata3D objectMetadata{serial,serial^0x1234u,serial^0x5678u};const LinearHdrCaptureRequestMetadata3D hdrMetadata{serial,serial^0x1234u,serial^0x5678u};
 for(unsigned frame=0;frame<D3D12Renderer::BufferedFrames*2;++frame)renderer.Render(draw,{0,0,0,1});renderer.WaitIdle();if(!renderer.RequestObjectIdReadback3D(objectMetadata)||!renderer.RequestLinearHdrReadback3D(hdrMetadata))return{};
 renderer.Render(draw,{0,0,0,1});renderer.WaitIdle();auto oid=renderer.TakeObjectIdReadback3D();auto hdr=renderer.TakeLinearHdrReadback3D();if(!hdr||!oid||!hdr->Complete()||!oid->Complete()||hdr->receipt.requestMetadata!=oid->requestMetadata||hdr->receipt.rasterProvenance!=oid->rasterProvenance||hdr->receipt.width!=oid->width||hdr->receipt.height!=oid->height)return{};
 const size_t pixelCount=size_t(hdr->receipt.width)*hdr->receipt.height;if(oid->pixels.size()!=pixelCount)return{};Capture result{std::move(*hdr),std::move(*oid)};result.mask.resize(pixelCount);result.rgb.resize(pixelCount);std::vector<uint8_t> identityMask(pixelCount);const unsigned width=result.hdr.receipt.width,height=result.hdr.receipt.height;double sum{};
 for(size_t pixel=0;pixel<pixelCount;++pixel){const auto* resolved=result.oid.Resolve(result.oid.pixels[pixel]);identityMask[pixel]=uint8_t(resolved&&*resolved==identity);result.rgb[pixel]={Channel(result.hdr,pixel,0),Channel(result.hdr,pixel,1),Channel(result.hdr,pixel,2)};}
 for(unsigned y=1;y+1<height;++y)for(unsigned x=1;x+1<width;++x){const size_t pixel=size_t(y)*width+x;result.mask[pixel]=identityMask[pixel]&&identityMask[pixel-1]&&identityMask[pixel+1]&&identityMask[pixel-width]&&identityMask[pixel+width];if(!result.mask[pixel])continue;const auto& rgb=result.rgb[pixel];sum+=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];++result.pixels;}
 if(stableMask&&result.mask!=stableMask->mask)return{};if(result.pixels)result.luma=float(sum/double(result.pixels));return result.pixels>=2000?std::optional<Capture>{std::move(result)}:std::optional<Capture>{};
}
bool SentinelDeltaOracle(const Capture& zero,const Capture& sentinel,const Capture& before,const Capture& after){double dot{},referenceEnergy{},deltaEnergy{},residualEnergy{},referenceLuma{},deltaLuma{};size_t eligible{},positive{};for(size_t pixel=0;pixel<zero.mask.size();++pixel){if(!zero.mask[pixel])continue;std::array<double,3> reference{},delta{};for(unsigned channel=0;channel<3;++channel){reference[channel]=double(sentinel.rgb[pixel][channel])-zero.rgb[pixel][channel];delta[channel]=double(after.rgb[pixel][channel])-before.rgb[pixel][channel];dot+=reference[channel]*delta[channel];referenceEnergy+=reference[channel]*reference[channel];deltaEnergy+=delta[channel]*delta[channel];}const double rl=.2126*reference[0]+.7152*reference[1]+.0722*reference[2],dl=.2126*delta[0]+.7152*delta[1]+.0722*delta[2];referenceLuma+=rl;deltaLuma+=dl;if(rl>.0005){++eligible;positive+=dl>0;}}if(referenceEnergy<=0||deltaEnergy<=0||!zero.pixels)return false;const double cosine=dot/std::sqrt(referenceEnergy*deltaEnergy),gain=dot/referenceEnergy;for(size_t pixel=0;pixel<zero.mask.size();++pixel)if(zero.mask[pixel])for(unsigned channel=0;channel<3;++channel){const double reference=double(sentinel.rgb[pixel][channel])-zero.rgb[pixel][channel],delta=double(after.rgb[pixel][channel])-before.rgb[pixel][channel],residual=delta-gain*reference;residualEnergy+=residual*residual;}const double referenceRms=std::sqrt(referenceEnergy/(zero.pixels*3.0)),residualRms=std::sqrt(residualEnergy/(zero.pixels*3.0));return referenceLuma/zero.pixels>.001&&deltaLuma/zero.pixels>.0005&&cosine>.995&&gain>=.70&&gain<=1.30&&residualRms<=std::max(.0003,.35*referenceRms)&&eligible&&double(positive)/eligible>=.85;}
bool SamePixels(const Capture& a,const Capture& b,float meanLimit,float maximumLimit){double sum{};float maximum{};size_t channels{};for(size_t pixel=0;pixel<a.mask.size();++pixel)if(a.mask[pixel])for(unsigned channel=0;channel<3;++channel){const float difference=std::abs(a.rgb[pixel][channel]-b.rgb[pixel][channel]);sum+=difference;maximum=std::max(maximum,difference);++channels;}return channels&&sum/channels<=meanLimit&&maximum<=maximumLimit;}
}

int main(){
 HWND window=CreateWindowExW(0,L"STATIC",L"ForwardPlusSmoke",WS_OVERLAPPED,0,0,480,270,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);if(!window)return 1;
 try{
  D3D12Renderer renderer;renderer.SetMaterialDerivedDataCacheDirectory({});renderer.Initialize(window,480,270,480,270,false);renderer.SetQualitySettings({false,false,false,false});const Mesh3D card=UvCard();const auto mesh=renderer.CreateMesh(card.vertices,card.indices);if(!mesh)return 2;const RenderObjectIdentity3D identity{{0x46504c5553434152ull,0x4453454e54494e45ull},1};uint64_t serial=0x7100;
  auto makeDraw=[&](unsigned fillerCount,bool sentinel){DrawList draw;const Camera3D camera{{.8f,.35f,-6.f},{0,0,4.f},{0,1,0},{ProjectionMode::Perspective,.82f,20.f,.2f,37.f}};draw.SetViewProjection(CreateViewProjectionMatrix(camera,480.f/270.f));draw.SetBackfaceCulling(false);draw.SetCameraCut3D(true);draw.SetDirectionalLight({{0,0,1},0.f,{1,1,1,1},0.f});draw.MeshInstance(mesh,CreateTransformMatrix({0,0,4},{},{1,1,1}),{.05f,.05f,.05f,1.f},{.6f,0,0,1},MeshRenderLayer3D::Opaque,{},1.f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false,1,0,false,DirectionalShadowAllCascades3D,ShadowCascadeSelection3D::Automatic,Matrix4::Identity(),false,1.f,MaterialAlphaMode3D::Opaque,.5f,false,identity);for(unsigned index=0;index<fillerCount;++index)draw.AddPointLight({{-.5f,0,2.f},6.f,{0,0,0,1},1e-8f+float(index)*1e-10f});if(sentinel)draw.AddPointLight({{.5f,0,2.f},6.f,{.05f,1.f,.1f,1},12.f});return draw;};
  {const auto warm=makeDraw(0,false);for(unsigned frame=0;frame<8;++frame)renderer.Render(warm,{0,0,0,1});renderer.WaitIdle();}const auto zero=CaptureCard(renderer,makeDraw(0,false),identity,++serial);if(!zero)return 3;const std::array<std::pair<unsigned,const char*>,4> cases{{{3,"3-4"},{62,"62-63"},{64,"64-65"},{255,"255-256"}}};
  const auto sentinel=CaptureCard(renderer,makeDraw(0,true),identity,++serial,&*zero);if(!sentinel||!(sentinel->luma>zero->luma+.01f)){std::cerr<<"Forward+ sentinel control failed zero="<<zero->luma<<" sentinel="<<(sentinel?sentinel->luma:-1.f)<<'\n';return 3;}std::cout<<"sentinelLuma="<<sentinel->luma-zero->luma<<'\n';
  // 同一 renderer 逐案交錯修改燈光，避免分組擷取掩蓋逐幀資源或 receipt 陳舊問題。
  for(const auto& [fillerCount,label]:cases){
   const auto before=CaptureCard(renderer,makeDraw(fillerCount,false),identity,++serial,&*zero);const auto beforeStats=renderer.GetStats();
   const auto after=CaptureCard(renderer,makeDraw(fillerCount,true),identity,++serial,&*zero);const auto afterStats=renderer.GetStats();
   const auto reset=CaptureCard(renderer,makeDraw(fillerCount,false),identity,++serial,&*zero);const auto resetStats=renderer.GetStats();
   std::cout<<"case="<<label<<" count="<<beforeStats.forwardPlusLightCount<<"->"<<afterStats.forwardPlusLightCount<<"->"<<resetStats.forwardPlusLightCount<<" dispatch="<<beforeStats.forwardPlusDispatches<<"->"<<afterStats.forwardPlusDispatches<<"->"<<resetStats.forwardPlusDispatches<<" luma="<<(before?before->luma:-1.f)<<"->"<<(after?after->luma:-1.f)<<"->"<<(reset?reset->luma:-1.f)<<'\n';
   if(!before||!after||!reset||beforeStats.forwardPlusLightCount!=fillerCount||afterStats.forwardPlusLightCount!=fillerCount+1||resetStats.forwardPlusLightCount!=fillerCount||!SentinelDeltaOracle(*zero,*sentinel,*before,*after)||!SamePixels(*before,*reset,1e-5f,1e-4f)){std::cerr<<"Forward+ sequential mutation oracle failed case="<<label<<'\n';return 4;}
  }
  const auto dispatches=renderer.GetStats().forwardPlusDispatches;renderer.SetForwardPlusPointLightsEnabled(false);const auto off=CaptureCard(renderer,makeDraw(255,true),identity,++serial,&*zero);if(!off||renderer.GetStats().forwardPlusDispatches!=dispatches||renderer.GetStats().forwardPlusResidentBytes||!SamePixels(*off,*zero,1e-5f,1e-4f))return 5;renderer.SetForwardPlusPointLightsEnabled(true);const auto restored=CaptureCard(renderer,makeDraw(0,true),identity,++serial,&*zero);if(!restored||!SentinelDeltaOracle(*zero,*sentinel,*zero,*restored)||renderer.GetStats().forwardPlusDispatches<=dispatches)return 6;
  const auto stats=renderer.GetStats();wchar_t validationMode[8]{};const bool expectGpuValidation=GetEnvironmentVariableW(L"AEVRYND_GPU_VALIDATION",validationMode,unsigned(std::size(validationMode)))&&validationMode[0]==L'1';if(stats.gpuValidationRequested!=expectGpuValidation||(expectGpuValidation&&(!stats.gpuValidationAvailable||!stats.gpuValidationExecuted||!stats.gpuValidationPassed))||stats.debugErrorCount||stats.debugWarningCount){std::cerr<<"validation receipt expected="<<expectGpuValidation<<" requested="<<stats.gpuValidationRequested<<" available="<<stats.gpuValidationAvailable<<" executed="<<stats.gpuValidationExecuted<<" passed="<<stats.gpuValidationPassed<<" errors="<<stats.debugErrorCount<<" warnings="<<stats.debugWarningCount<<'\n';for(size_t index=0;index<stats.debugErrorIdCount;++index)std::cerr<<"error["<<index<<"] id="<<stats.debugErrorIds[index]<<' '<<stats.debugErrorDescriptions[index]<<'\n';for(size_t index=0;index<stats.debugWarningIdCount;++index)std::cerr<<"warning["<<index<<"] id="<<stats.debugWarningIds[index]<<' '<<stats.debugWarningDescriptions[index]<<'\n';return 8;}
  std::cout<<"FORWARD_PLUS_D3D12_OK pixels="<<sentinel->pixels<<" restored="<<restored->luma-off->luma<<'\n';
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';DestroyWindow(window);return 7;}DestroyWindow(window);return 0;
}
